define([],function(){function uuid(){if (window.crypto && window.crypto.randomUUID){return window.crypto.randomUUID().replace(/-/g,'');}return 'sess'+Date.now()+Math.random().toString(36).substring(2,12);}function getIntervalBarColor(canvas,property,fallback){var value=window.getComputedStyle(canvas).getPropertyValue(property);return value ? value.trim() :fallback;}function showResumeNotice(seconds,config,Utils){var existing=document.getElementById('videotrack-resume-notice');if (existing){existing.parentNode.removeChild(existing);}var formatted=Utils.formatSeconds(seconds);var notice=document.createElement('div');notice.id='videotrack-resume-notice';notice.className='videotrack-resume-notice alert alert-info alert-dismissible mt-1';notice.setAttribute('role','status');notice.setAttribute('aria-live','polite');var text=document.createElement('span');text.textContent=config.resumelabel+' '+formatted+'.';notice.appendChild(text);var btn=document.createElement('button');btn.type='button';btn.className='btn-close ms-2';btn.setAttribute('aria-label',config.dismisslabel);btn.addEventListener('click',function(){if (notice.parentNode){notice.parentNode.removeChild(notice);}});notice.appendChild(btn);var shell=document.querySelector('.videotrack-player-shell');if (shell){shell.insertBefore(notice,shell.firstChild);}window.setTimeout(function(){if (notice.parentNode){notice.parentNode.removeChild(notice);}},6000);}function setNoteButtonState(saveBtn,playing){if (!saveBtn){return;}saveBtn.setAttribute('aria-disabled',playing ? 'false' :'true');saveBtn.classList.toggle('videotrack-note-save-disabled',!playing);}function appendNoteRow(noteid,videotime,text,config,Utils){var list=document.getElementById('videotrack-notes-list');if (!list){return;}var li=document.createElement('li');li.className='videotrack-note-item';li.dataset.noteid=noteid;var timeSpan=document.createElement('span');timeSpan.className='videotrack-note-time text-muted me-1 small';timeSpan.textContent=Utils.formatSeconds(videotime);li.appendChild(timeSpan);var textSpan=document.createElement('span');textSpan.className='videotrack-note-text';textSpan.textContent=text;li.appendChild(textSpan);var delBtn=document.createElement('button');delBtn.type='button';delBtn.className='btn btn-link btn-sm videotrack-delete-note ms-1';delBtn.dataset.noteid=noteid;delBtn.textContent=config.removenotelabel;li.appendChild(delBtn);list.appendChild(li);}function getRemainingNoteChars(textarea,config,Utils){var maxLength=parseInt(textarea.getAttribute('maxlength'),10);if (!isFinite(maxLength) || maxLength <= 0){maxLength=Utils.safeInt(config.notemaxlength,2000);}return Math.max(0,maxLength - textarea.value.length);}function removePoster(overlay){if (overlay && overlay.parentElement){overlay.style.opacity='0';window.setTimeout(function(){if (overlay && overlay.parentElement){overlay.parentElement.removeChild(overlay);}},300);}}return{uuid:uuid,getIntervalBarColor:getIntervalBarColor,showResumeNotice:showResumeNotice,setNoteButtonState:setNoteButtonState,appendNoteRow:appendNoteRow,getRemainingNoteChars:getRemainingNoteChars,removePoster:removePoster};});
